<?php $this->layout('layouts/admin', ['title' => 'Danh mục tour', 'pageTitle' => 'Quản lý danh mục', 'activeMenu' => 'category']) ?>
<?php $this->start('page') ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="h4 fw-bold mb-1">Danh mục tour</h2><p class="text-secondary mb-0"><?= count($categories) ?> danh mục</p></div><a href="/admin/categories/create" class="btn btn-warning fw-bold"><i class="bi bi-plus-lg me-1"></i>Thêm danh mục</a></div><div class="card border-0 shadow-sm rounded-4"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Mã</th><th>Tên danh mục</th><th>Mô tả</th><th>Số tour</th><th class="text-end">Thao tác</th></tr></thead><tbody><?php foreach($categories as $category):?><tr><td>#<?= (int)$category['categoryId'] ?></td><td><strong><?= $this->e($category['name']) ?></strong></td><td><span class="d-inline-block text-truncate" style="max-width:420px"><?= $this->e($category['description'] ?: '—') ?></span></td><td><?= (int)($category['tourCount'] ?? 0) ?></td><td><div class="d-flex justify-content-end gap-1"><a href="/admin/categories/edit/<?= (int)$category['categoryId'] ?>" class="btn btn-sm btn-outline-dark"><i class="bi bi-pencil"></i></a><form action="/admin/categories/delete/<?= (int)$category['categoryId'] ?>" method="POST" onsubmit="return confirm('Xóa danh mục này?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$categories):?><tr><td colspan="5" class="text-center text-secondary py-5">Chưa có danh mục.</td></tr><?php endif;?></tbody></table></div></div>
<?php $this->stop() ?>
